<?php require __DIR__.'/../includes/admin_auth.php';$pdo=db();$metrics=['Total rooms'=>'SELECT COUNT(*) FROM rooms','Available rooms'=>"SELECT COUNT(*) FROM rooms WHERE status='AVAILABLE'",'Occupied rooms'=>"SELECT COUNT(*) FROM rooms WHERE status='OCCUPIED'",'Maintenance rooms'=>"SELECT COUNT(*) FROM rooms WHERE status='MAINTENANCE'",'Today check-ins'=>"SELECT COUNT(*) FROM reservations WHERE check_in=CURDATE() AND status='CONFIRMED'",'Today check-outs'=>"SELECT COUNT(*) FROM reservations WHERE check_out=CURDATE() AND status='CHECKED_IN'",'Pending reservations'=>"SELECT COUNT(*) FROM reservations WHERE status='PENDING'",'Revenue'=>"SELECT COALESCE(SUM(amount),0) FROM payments WHERE payment_status='PAID'"];$pageTitle='Admin dashboard';require __DIR__.'/../includes/header.php';?><h1>Hotel management dashboard</h1><div class="stats"><?php foreach($metrics as $name=>$q):?><div class="stat"><b><?=str_contains($name,'Revenue')?'₱'.number_format((float)$pdo->query($q)->fetchColumn(),2):$pdo->query($q)->fetchColumn()?></b><?=e($name)?></div><?php endforeach;?></div><div class="grid"><a class="card" href="<?=url('rooms/index.php')?>"><h3>Rooms</h3><p class="muted">Browse rooms and availability.</p></a><a class="card" href="<?=url('admin/reservations/index.php')?>"><h3>Reservations</h3><p class="muted">Confirm, reject, check in, and check out guests.</p></a><a class="card" href="<?=url('admin/logs/index.php')?>"><h3>Activity logs</h3><p class="muted">Review important actions.</p></a></div><?php require __DIR__.'/../includes/footer.php'; ?>
